class PlaceOrderService {
  public:
    PlaceOrderService(OrderRepository& orders, CustomerRepository& customers, UnitOfWork& uow)
        : orders_(orders), customers_(customers), uow_(uow) {}

    std::expected<OrderId, Error> place(const PlaceOrderCommand& cmd) {
        auto tx = uow_.beginTransaction();               // TransactionGuard rolls back on destruction
        auto customer = customers_.ofId(cmd.customerId);
        if (!customer) return std::unexpected(customer.error());
        auto order = customer->placeOrder(cmd.items);
        if (!order) return std::unexpected(order.error());
        orders_.add(*order);
        if (auto committed = tx.commit(); !committed)
            return std::unexpected(committed.error());
        return order->id();                              // one commit per use case
    }

  private:
    OrderRepository& orders_;
    CustomerRepository& customers_;
    UnitOfWork& uow_;
};
